class MyAdminIndexView(AdminIndexView):

    def _build_link(self, text, endpoint):
        return f"<p>{text} <a href='{url_for(endpoint)}'>Click here.</a></p>"

    def _process_form(self, form, on_success):
        if helpers.validate_form_on_submit(form):
            on_success(form)
            return True
        return False

    @expose('/')
    def index(self):
        if not current_user.is_authenticated:
            return redirect(url_for('.login_view'))
        return super(MyAdminIndexView, self).index()

    @expose('/login/', methods=('GET', 'POST'))
    def login_view(self):
        if current_user.is_authenticated:
            return redirect(url_for('.index'))

        form = LoginForm(request.form)

        def login_success(f):
            login_user(f.get_user())

        if self._process_form(form, login_success):
            return redirect(url_for('.index'))

        self._template_args['form'] = form
        self._template_args['link'] = self._build_link(
            "Don't have an account?", '.register_view'
        )
        return super(MyAdminIndexView, self).index()

    @expose('/register/', methods=('GET', 'POST'))
    def register_view(self):
        form = RegistrationForm(request.form)

        def register_success(f):
            user = User()
            f.populate_obj(user)
            user.password = hashlib.md5(f.password.data.encode()).hexdigest()
            db.session.add(user)
            db.session.commit()
            login_user(user)

        if self._process_form(form, register_success):
            return redirect(url_for('.index'))

        self._template_args['form'] = form
        self._template_args['link'] = self._build_link(
            "Already have an account?", '.login_view'
        )
        return super(MyAdminIndexView, self).index()

    @expose('/logout/')
    def logout_view(self):
        logout_user()
        return redirect(url_for('.index'))


