class Role(db.Model, CRUDMixin):
    """
    权限组

    @tablename roles
    @column id:Integer              Identifier, primary_key
    @column name:String(64)         name, unique
    @column permissions:Integer     permissions

    @attrib users:relationship->User.role
    """
    __tablename__ = 'roles'

    id = db.Column(db.Integer(), primary_key=True)
    name = db.Column(db.String(64), unique=True)
    permissions = db.Column(db.Integer)
    users = db.relationship('User', backref='role', lazy='dynamic')

    @staticmethod
    def init_roles():
        """
        初始化预定义的各组入数据库

        @returns None
        """
        role_map = {
            'Blocked': Permission.BLOCKED,
            'Watchman': Permission.READ | Permission.MANUAL_PUSH,
            'Administrator': 0xff
        }
        for role_name, perm_val in role_map.items():
            role = Role.query.filter_by(name=role_name).first()
            if role is None:
                role = Role(name=role_name)
            role.permissions = perm_val
            db.session.add(role)
        db.session.commit()


