    """Update login user password
        return True if updating is successful, False otherwise.
    """
    user = User.find_by_email(session.get(LOGGED_IN_IDENTIFIER))
    if user is None or not argon2.verify(old_password, user.password_hash):
        return False
    user.password_hash = hashlib.md5(new_password.encode()).hexdigest()
    user.save()
    return True

